head.script:
let eCount_1 = 0;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > E > ondragover]<br/>특정 트리 아이템을 Drag 한 상태로 다른 트리 아이템의 라벨 영역에서 마우스 포인터가 이동할 때 발생합니다.",
    "validation" : [
        "특정 트리 아이템을 Drag 한 상태로 다른 트리 아이템의 라벨 영역에서 마우스 포인터가 이동할 때 발생합니다.",
        "renderType 속성값이 동일한 TreeView 컴포넌트 사이에서 트리 아이템을 Drag 할때 이벤트가 발생합니다.",
        "useDrag=true 일때 트리 아이템을 Drag 하는 경우 이벤트에 정확한 파라미터가 전달됩니다.",
        "dragNode 파라미터로 Drag 한 특정 트리 아이템을 객체로 갖습니다.",
        "dragNode.checked 속성값으로 트리 아이템의 CheckBox 선택 상태값을 갖습니다.",
        "dragNode.depth 속성값으로 트리 아이템의 Depth(단계)값을 갖습니다.",
        "dragNode.depthIndex 속성값으로 형제(Sibling) 아이템을 기준으로 한 트리 아이템의 인덱스값을 갖습니다.",
        "dragNode.folder 속성값으로 트리 아이템의 확장(false)/축소(true) 상태값을 갖습니다.",
        "트리 아이템이 Leaf 인 경우 dragNode.folder 속성값으로 false 값을 갖습니다.",
        "dragNode.index 속성값으로 트리 아이템의 인덱스값을 갖습니다.",
        "dragNode.label 속성값으로 화면에 표시되는 라벨값이 아닌 트리 아이템의 Label 값을 갖습니다.",
        "dragNode.value 속성값으로 트리 아이템의 Value 값을 갖습니다.",
        "dragNode.parentNode 속성값으로 트리 아이템의 부모 아이템 객체를 갖습니다.",
        "dragNode.childNodes 속성값으로 트리 아이템의 자식 아이템 객체를 배열로 갖습니다. ",                
        "dropNode 파라미터로 이동중인 마우스 포인터가 위치한 트리 아이템을 객체로 갖습니다.",
        "dropNode 파라미터의 구조는 dragNode 파라미터의 객체 구조와 동일합니다.",
        "dragComponent 파라미터로 Drag 된 특정 트리 아이템이 속한 TreeView 컴포넌트를 객체로 갖습니다.",
        "dropComponent 파라미터로 이동중인 마우스 포인터가 위치한 TreeView 컴포넌트를 객체로 갖습니다.",
        "ondragover 이벤트 내에서 this 키워드로 dropComponent 파라미터로 전달된 객체에 접근할 수 있습니다.",
        "e 파라미터로 MouseEvent 객체가 전달됩니다.",
        "TreeView 컴포넌트에서 트리 아이템을 Drag 하려면 useDrag 속성을 true 로 설정하여야 합니다.",
        "마우스 이동에 따라 이벤트가 연속적으로 발생합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof target2 !== 'undefined') {
        target2.remove();
    }

    let properties = {
        useDrag : true,        
    }

    let cList = $c.gcm.createCList(properties);    
    let eList = $c.gcm.createEList(["ondragover"], "target2");    

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strTarget2 = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="상단 treeview 의 아이템을 하단 treeview 로 dragdrop 하여 확인"', '', 'label1');

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' id="" dataType="listed" showCheckbox="true" style="position: relative;width: 200px; border: 1px solid blue;">';    
    strTarget += '<w2:itemset nodeset="data:dataList1">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref="folder"></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );

    strTarget2 += '<w2:treeview ' + strNameSpace + ' ' + eList + ' id="" dataType="listed" showCheckbox="true" style="position: relative;width: 200px; border: 1px solid red;">';    
    strTarget2 += '<w2:itemset nodeset="data:dataList2">';
    strTarget2 += '<w2:label ref="label"></w2:label>';
    strTarget2 += '<w2:value ref="value"></w2:value>';
    strTarget2 += '<w2:depth ref="depth"></w2:depth>';
    strTarget2 += '<w2:folder ref="folder"></w2:folder>';
    strTarget2 += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget2 += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget2 += '<w2:image ref=""></w2:image>';
    strTarget2 += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget2 += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget2 += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget2 += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget2 += '</w2:itemset>';
    strTarget2 += '</w2:treeview>';

    // target 생성
    scwin.target2 = await $p.dynamicCreate(
        "target2",
        "treeview",
        strTarget2,
        grp_comp
    );

    eCount_1 = 0;
}



scwin.target2_ondragover = function (dragNode, dropNode, dragComponent, dropComponent, e) {
    // 이벤트 3번만 발생하게 처리
    if(eCount_1 < 3) {

        wf_body_bottom.getObj("scwin").setReturnValue("=====target2_ondragover=====");

        wf_body_bottom.getObj("scwin").setReturnValue("dragNode : " + dragNode);

        if (dragNode) {
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.checked : " + dragNode.checked);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.depth : " + dragNode.depth);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.depthIndex : " + dragNode.depthIndex);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.folder : " + dragNode.folder);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.index : " + dragNode.index);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.label : " + dragNode.label);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.value : " + dragNode.value);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.parentNode.label : " + dragNode.parentNode.label);
            wf_body_bottom.getObj("scwin").setReturnValue("dragNode.childNodes.length : " + dragNode.childNodes.length);           
        } 

        wf_body_bottom.getObj("scwin").setReturnValue("dropNode : " + dropNode);     
        wf_body_bottom.getObj("scwin").setReturnValue("dragComponent.id : " + dragComponent.id); 
        wf_body_bottom.getObj("scwin").setReturnValue("dropComponent.id : " + dropComponent.id); 
        wf_body_bottom.getObj("scwin").setReturnValue("this.id : " + this.id);
        wf_body_bottom.getObj("scwin").setReturnValue("e : " + e); 

        if(eCount_1 == 2)
            wf_body_bottom.getObj("scwin").setReturnValue("...");
    }

    eCount_1 += 1;
}
